// ── SCHEDULE ────────────────────────────────────────────────────────────────
// Both boundaries are MONDAYS so a program never changes mid-week:
//   V3 return block  Jul 28 – Aug 2
//   V4 (Southpaw)    Mon Aug 3 onwards
//   Physio hidden until Mon Aug 10
//
// Southpaw week: 6 training days + Wednesday. Wednesday is the rest day, and
// from Aug 10 it also carries the morning physio sequence, so before Aug 10 it
// strips to zero exercises and reads as pure rest.

// The Sunday exemption is for the LEGACY programs (V1-V3), where Sunday is
// Active Recovery and its entire content is physio: stripping would empty the
// day and silently turn it into a second rest day. Southpaw moves physio to
// Wednesday and makes Sunday a full Legs & Core session, so the exemption is
// inert for V4 and Wednesday correctly strips to zero before Aug 10.
// Memoised on the source object: only four programs can ever be passed in, and
// programFor() runs in a loop when walking back over a streak.
const _spCache=new Map();
function _sp(p){
  if(_spCache.has(p))return _spCache.get(p);
  // Legacy programs put the physio block on Sunday, so stripping physio there
  // would empty the day. Southpaw's own Sunday is the rest day and carries that physio itself.
  const legacySunday=p!==PROG_V4;
  const o={};
  for(const[d,v]of Object.entries(p))
    o[d]=(d==="Sunday"&&legacySunday)?{...v}:{...v,exercises:v.exercises.filter(e=>e.cat!=="physio")};
  _spCache.set(p,o);return o;
}

// Which program was active on a GIVEN date, rather than only "right now".
// History matters: physio returns Aug 10, so anything reasoning about past
// dates (the streak) has to ask what was scheduled THEN, or days that were
// legitimately lighter get re-read against a later, fuller schedule.
// Which program version a plan was generated against. Stamped onto weekPlans so
// an override written for an older program cannot inject into a newer one.
export function programKeyFor(date){
  return date>=new Date(2026,7,3)?"v4"
    :date>=new Date(2026,6,28)?"v3"
    :date>=new Date(2026,5,1)?"v2":"v1";
}

// New movements are introduced one per week, not all at once: an unfamiliar
// pattern is where a spine flare comes from, and a delayed nerve reaction is
// only attributable if a single thing changed. An exercise carries from:"ISO"
// and simply does not exist before that date.
const _stCache=new Map();
function _stage(p,date){
  const t=date.getTime();
  const cut=[...new Set(Object.values(p).flatMap(v=>(v.exercises||[]).map(e=>e.from).filter(Boolean)))]
    .filter(d=>t<new Date(d+"T00:00:00").getTime());
  if(!cut.length)return p;
  const key=p===PROG_V4?"v4":"x";
  const ck=key+"|"+cut.sort().join(",");
  if(_stCache.has(ck))return _stCache.get(ck);
  const o={};
  for(const[d,v]of Object.entries(p))
    o[d]={...v,exercises:(v.exercises||[]).filter(e=>!e.from||!cut.includes(e.from))};
  _stCache.set(ck,o);return o;
}

export function programFor(date){
  const base=date>=new Date(2026,7,3)?PROG_V4:date>=new Date(2026,6,28)?PROG_V3:date>=new Date(2026,5,1)?PROG_V2:PROG_V1;
  return _stage(date<new Date(2026,7,10)?_sp(base):base,date);
}

const _pd=new Date();
// Human-readable name per program version, so the AI can be told what it is
// editing rather than inferring it from the exercise list.
export const PROG_NAME={v1:"original rehab program",v2:"program v2",v3:"program v3",
  v4:"Southpaw (Jake Gyllenhaal) hypertrophy program"};

export const PROG=programFor(_pd);

// Is this date a rest day for NUTRITION purposes, i.e. no gym work?
//
// Deliberately "no GYM exercises" rather than "no exercises at all", because
// from Aug 10 Wednesday carries a 25-minute morning physio sequence. That is
// recovery, not a training session, and it must still get the rest-day active
// calorie target. The same rule reproduces the old behaviour for V1-V3, whose
// Sunday is physio-only Active Recovery.
//
// Note this is NOT the same question as the workout streak's rest day, which
// asks "is there anything at all to log here" and so keys off a completely
// empty day. Wednesday after Aug 10 is a rest day for calories but a day you
// still tick off for the streak.
// PR history is keyed by a slug of the exercise NAME, so renaming an exercise
// orphans its history. Southpaw uses the gym's own names for four machines that
// already have logged sets under their catalogue names, so those map back.
// new slug -> the slug the history was actually written under.
// The one slug rule. Trailing/leading separators are stripped: 30 exercise
// names end in ")" and without the trim they produced keys like
// "cable_crossover_high_to_low_", which read back as a name with a stray gap.
// Weight rounded to one decimal. The HealthKit shortcut sends float noise
// ("136.00000001"), which is meaningless precision on a bathroom scale and
// leaks into the PDF, the CSV and the AI prompts verbatim. Applied at every
// write AND on read, so rows already stored wrong are healed rather than
// needing a migration everyone has to run.
export function kg1(v){
  // null/undefined/"" must stay null, not become 0: Number(null) is 0 and
  // finite, so a missing weigh-in would render as 0 kg and drag every average.
  if(v===null||v===undefined||v==="")return null;
  const n=Number(v);
  return Number.isFinite(n)?Math.round(n*10)/10:null;
}

export function prSlug(name){
  return String(name||"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"");
}

